f=main():$i64{
  let input=s.trim(io.readln());
  let inner=s.slice(input;1;s.len(input)-1);
  let objs=s.split(inner;"},{");
  let total=mut.0;
  let completed=mut.0;
  let i=mut.0;
  lp(i<objs.len()){
    let raw=objs.get(i);
    let nmark=s.indexof(raw;"\"objective\":\"");
    let aftern=s.slice(raw;(nmark as $u64)+13;s.len(raw));
    let q=s.indexof(aftern;"\"");
    let name=s.slice(aftern;0;q as $u64);
    let cmark=s.indexof(raw;"\"completed\":");
    let afterc=s.slice(raw;(cmark as $u64)+12;s.len(raw));
    let isdone=s.startswith(s.trim(afterc);"true");
    total=total+1;
    let pct=mut.0;
    let fill=mut.0;
    if(isdone){pct=100;fill=10;completed=completed+1};
    io.println(s.concat(s.concat(label(name);bar(fill));s.concat(" ";s.concat(s.fromint(pct);"%"))));
    i=i+1
  };
  let overall=mut.0;
  let ofill=mut.0;
  if(total>0){
    overall=(completed*100)/total;
    ofill=(completed*10)/total
  };
  io.println(s.concat(s.concat(label("Overall");bar(ofill));s.concat(" ";s.concat(s.fromint(overall);"%"))));
  <0
}

