let students=mut.@("");students=@();lp(1=1){let line=io.readln();if(s.len(line)=0){br};let t=s.trim(line);if(s.len(t)>0){students=students+@(t)}};
let idx=mut.0;let r=mut.0;lp(r<rows){let row=mut."";let c=mut.0;lp(c<cols){let name=mut."";if(idx<students.len()){name=students.get(idx);idx=idx+1};if(c=cols-1){row=s.concat(row;name)}el{row=s.concat(row;pad(name))};c=c+1};io.println(row);r=r+1};
